      //       "thumbnail": "https://cdn.i-scmp.com/sites/default/files/styles/700x400/public/d8/images/canvas/2025/11/25/6cbfad46-aa4e-4f67-ae4f-8717a6fa7c37_0d463772.jpg?itok=mbHmv6Bb&v=1764057285",
