      //       },
      //       "thumbnail": "https://oc-media.org/_next/image/?url=https%3A%2F%2Fassets.bucket.fourthestate.app%2Foc-media-prod%2Fcontent%2Fimages%2F2025%2F09%2FSpayka-3_9_2025.jpg&w=3840&q=90",
