      //       "thumbnail": "https://npr.brightspotcdn.com/dims4/default/0432d9f/2147483647/strip/true/crop/2295x1827+0+0/resize/880x701!/quality/90/?url=http%3A%2F%2Fnpr-brightspot.s3.amazonaws.com%2Fba%2F04%2F4be8d6ec43028a4a6036d994f9c3%2F0702-nika-family-courtesy.jpg",
